}

/** Inyecta el `logEvent` real (o un capturador de test). Mismo patrón DI que `setGetCwdFn` en `@thyrox/storage`. */
export function setLogEventFn(
  fn: (name: string, metadata?: Record<string, unknown>) => void,
): void {
