 * la plataforma sin tocar el proceso real.
 */
export async function sweepOrphanSpareSockets(
  dir: string,
  activePtySockets: ReadonlySet<string>,
  platformFn: () => NodeJS.Platform = osPlatform,
): Promise<number> {
  if (platformFn() === 'win32') return 0
