    }
    if (name.endsWith('.claim.sock')) {
      const ptyName = `${name.slice(0, -'.claim.sock'.length)}.pty.sock`
      if (!activePtySockets.has(join(dir, ptyName))) await unlink(join(dir, name)).catch(() => {})
